    'g.foe.name.driller': 'Bohrläufer', 'g.foe.name.sentry': 'Wächter', 'g.foe.name.crane': 'Kranarm', 'g.foe.name.drone': 'Dämmerdrohne', 'g.foe.name.wisp': 'Schattenwesen',
    'g.foe.hearts': 'Herzen',
    'g.foe.funke.first': 'Achtung, eine verwirrte Maschine! Wenn ihr Auge aufleuchtet, kommt gleich etwas — dann weich zur Seite aus.',
    'g.foe.funke.weak': 'Ihr Kern glüht durch die Lüftung — dort ist sie verwundbar.',
