    'g.set.sec.air': 'Luft & Wetter',
    'g.set.sec.steer': 'Steuerung',
    'g.set.sec.play': 'Spielen',
    'g.set.preset.tip': 'Eine Stufe stellt alles auf einmal ein: „Sehr niedrig“ für alte Laptops, „Ultra“ für starke Grafikkarten.',
    'g.set.renderDist.tip': 'Wie weit du alles im Detail siehst (Ring 0, in Chunks zu 16 Blöcken). Auf Hoch und Ultra zeigt Ring 1 dahinter bis etwa 1 km die Formen – Hügel, Städte, Türme –, Ring 2 den Horizont. Die Weite kostet am meisten.',
    'g.set.horizon.tip': 'Das Land dahinter, als grobes Gelände bis 5 km.',
    'g.set.shadows.tip': 'Schatten von Sonne und Blöcken; höhere Stufen sind schärfer und weicher.',
    'g.set.sunShadows.tip': 'Weiche Schatten der Sonne über das ganze Gelände.',
    'g.set.rays.tip': 'Lichtstrahlen zwischen Bäumen und Bergen am Tag.',
    // t-light2 · Das Licht (light2.js)
    'g.set.l2Light': 'Licht-Modell',
    'g.set.l2Light.tip': 'Schatten in der Farbe des Himmels, warmes Licht vom Boden zurück, weiche Blätter und Haut, Lampen werfen Lichtinseln, der Mond scheint kühl.',
    'g.set.l2Ssao': 'Kontaktschatten',
    'g.set.l2Ssao.tip': 'Weiche Schatten in Ecken, unter Dächern und Balkonen und wo Dinge den Boden berühren — mehr Tiefe im Bild.',
    'g.set.l2SsaoV': ['Aus', 'Leicht', 'Mittel', 'Fein'],
    'g.set.l2Vol': 'Lichtstrahlen im Raum',
    'g.set.l2Vol.tip': 'Das Sonnenlicht wird in der Luft sichtbar: Strahlen durch Glasdächer, zwischen Bäumen, in die Hangarhalle. Braucht Sonnenstrahlen und Schatten.',
    'g.set.l2Air': 'Luft & Dunst',
    'g.set.l2Air.tip': 'Dunst in Tälern und über Wasser, Morgennebel, ferne Hügel verblassen in der Farbe des Horizonts.',
    'g.set.l2Grade': 'Farbstimmung',
    'g.set.l2Grade.tip': 'Jede Tageszeit hat ihre Farben: die goldene Stunde warm, die Dämmerung violett, die Nacht türkis mit warmen Lampen; Leuchten glühen, die Sonne blendet sanft.',
    'g.set.lvHaze': 'Sonnendunst',
    'g.set.lvHaze.tip': 'Die Luft zwischen dir und dem Land: zur Sonne hin ein warmer Schleier über der Ferne, von ihr weg ein kühler — die Hügel stehen hintereinander wie gemalte Ebenen.',
    'g.set.lvPal': 'Filmpalette',
    'g.set.lvPal.tip': 'Die Grüntöne wie im Trickfilm: grelles Wiesengrün wird im Licht ein warmes Saftgrün, im Schatten ein Blaugrün. Haut, Holz und Lampen bleiben, wie sie sind.',
    'g.set.lvSoft': 'Weite Ferne',
    'g.set.lvSoft.tip': 'Das ferne Land wird weicher, wie hinter einer Kameralinse — das Nahe bleibt scharf. Eine kleine Zusatzstufe in Viertelauflösung.',
    'g.set.lvWrap': 'Lichtsaum',
    'g.set.lvWrap.tip': 'Heller Himmel hinter einer Silhouette strahlt sanft über ihre Kante — Bäume, Türme und Menschen stehen im Licht statt davor.',
    'g.set.lvTone': 'Mondlicht & Weltenfarben',
    'g.set.lvTone.tip': 'Nachts silberblaues Mondlicht, warme Lampen leuchten sanft, der Himmel nie ganz schwarz — und jede Welt ihre eigene Farbstimmung (Aquamarin, Ocker, Zinnober, Opal, Basalt, die Station).',
    'g.set.lvMeadow': 'Wiesenruhe',
    'g.set.lfPools': 'Lichtpfützen',
    'g.set.lfPools.tip': 'Nachts warme Lichtinseln: Laternen, Feuer, Fenster und Feenlichter werfen weiche, farbige Lichtpfützen auf Straßen, Wände und Leute — Mauern werfen Schatten, getragene Laternen wandern mit.',
    'g.set.lvMeadow.tip': 'Das Gras nah vor dir ruhiger, wie gemalt: weniger Pixelrauschen, große weiche Farbflecken über die Wiese.',
    'g.set.xDepth': 'Tiefe',
    'g.set.xDepth.tip': 'Ecken, Fugen und Füße werfen dunklere Kontaktschatten — auch im Sonnenlicht. Dinge stehen auf dem Boden statt zu schweben. Braucht die Kontaktschatten.',
    'g.set.xDepthV': ['Aus', 'Stark', 'Kino'],
    'g.set.xClar': 'Klarheit',
    'g.set.xClar.tip': 'Mehr Kontrast im Nahen: Dunkles hebt sich von Hellem ab, Formen werden klarer. Fast kostenlos (nutzt die Weite-Ferne-Kopie).',
    'g.set.xBlur': 'Filmkamera',
    'g.set.xBlur.tip': 'Bewegungsunschärfe wie bei einer Filmkamera — nur in Kamerafahrten und Trailern, nie beim Spielen.',
    'g.set.xRange': 'Tonumfang',
    'g.set.xRange.tip': 'Volle Helligkeitsspanne: helle Flächen leuchten, Schatten werden tagsüber satt dunkel, die Mitte bleibt. Kostet fast nichts.',
    'g.set.qLeaf': 'Laubkronen',
    'g.set.qLeaf.tip': 'Baumkronen als runde Blätterballen: Licht und Schatten über die ganze Krone, warmer Rand im Gegenlicht, ausgefranste Ränder statt Blätterwürfel. Braucht schöne Blätter. Kostet wenig.',
    'g.set.qSky': 'Farbdrehbuch',
    'g.set.qSky.tip': 'Ein Himmel, der zum Boden passt: tagsüber warmer Dunst am Horizont und klares Blau statt Violett, das All nur ganz oben. Kostet nichts.',
    'g.set.qPlaza': 'Platzbelag',
    'g.set.qPlaza.tip': 'Helle Platzböden als warmer Stein mit Platten, Fugen und Gebrauchsspuren – sie blenden nicht mehr. Kostet wenig.',
    'g.set.qGrass': 'Wiese',
    'g.set.qGrass.tip': 'Gras als üppige Wiese: weiche Farbflecken, keine sichtbaren Kacheln, in der Nähe Halmbüschel mit dunklen Wurzeln und hellen Spitzen, die sich im Wind wiegen. Kostet mittel.',
    'g.set.qIsle': 'Schwebeinseln',
    'g.set.qIsle.tip': 'Schwebende Inseln mit gerundeter Felsunterseite, Gesteinsschichten und Moos, sanftem Licht vom Land darunter und einem weichen Schatten auf dem Boden. Kostet wenig.',
    'g.set.qCrown': 'Fernkronen',
    'g.set.qCrown.tip': 'Baumkronen bleiben auch in der Ferne rund, ihre Schatten haben ausgefranste Ränder statt Quadrate; Blütenkronen sind innen heller. Braucht Laubkronen. Kostet wenig.',
    'g.set.qRound': 'Runde Kronen',
    'g.set.qRound.tip': 'Baumkronen als gerundete Laubmassen statt Würfeln: Ecken und Kanten der Krone werden rund. Nur das Bild, die Blöcke bleiben, wie sie sind. Kostet wenig.',
    'g.set.magic.tip': 'Wie stark der Sternenhimmel am Tag durchscheint.',
    'g.set.scale.tip': 'Mit weniger Auflösung rechnet das Spiel schneller; das Bild wird hochgerechnet.',
    'g.set.tsr.tip': 'Rechnet klein und stellt scharf hoch: mehr Bilder pro Sekunde, fast gleich scharf.',
    'g.set.fadeIn.tip': 'Was in der Ferne erscheint, blendet weich ein (mit R9 Super Resolution). Aus: alles erscheint sofort ganz. Ganz nah wächst es immer kurz aus dem Boden.',
    'g.set.fxaa.tip': 'Glättet Treppen an den Kanten. Nur ohne Super Resolution.',
    'g.set.sharpen.tip': 'Macht das Bild knackiger; kostet fast nichts.',
    'g.set.dynRes.tip': 'Sinken die Bilder pro Sekunde, werden zuerst Schatten und Details angepasst. Das Bild wird nie unscharf.',
    'g.set.lite.tip': 'Flache Materialien ohne Relief und Glanz: am schnellsten.',
    'g.set.look': 'Blöcke',
    'g.set.look.tip': 'Wie Blöcke aussehen: jeder für sich wie im Original, oder weiche, verbundene Hügel.',
    'g.set.look.classic': 'Klassisch',
    'g.set.look.classic.tip': 'Jeder Block steht für sich, wie im Original.',
    'g.set.look.seamless': 'Nahtlos',
    'g.set.look.seamless.tip': 'Weiche Hügel und verbundene Glasflächen.',
    'g.set.particles.tip': 'Staub, Blätter, Funken und Rauch: mehr heißt lebendiger.',
    'g.set.clouds.tip': 'Wolken am Himmel: schnell oder schön, mit Schatten und Tiefe.',
    'g.set.bloom.tip': 'Helle Lichter strahlen ein wenig.',
    'g.set.fancyLeaves.tip': 'Blätter mit Lücken und Tiefe statt flacher Karten.',
    'g.set.smoothPlants.tip': 'Palmen mit echten Wedeln statt Blockkronen, schlank und weich wie im Trailer. Aus = Blockbild.',
    'g.set.smoothPlantsV': ['Aus', 'Einfach', 'Voll'],
    'g.set.smoothFurn': 'Echte Möbel',
    'g.set.smoothFurn.tip': 'Sofas, Betten, Lampen, Küchen und Pflanzen als runde, weiche Möbel aus Stoff, Holz, Metall und Glas statt Würfelmöbel; Lampenschirme leuchten. Aus = Blockbild.',
    'g.set.smoothFolk': 'Echte Menschen',
    'g.set.smoothFolk.tip': 'Die Dorfbewohner in der Nähe (bis 24 Blöcke) mit runden, weichen Formen statt Würfelstufen: Gesichter, Kleidung und Haare glatt, alle in einer Zeichnung. Weiter weg und aus = die Voxel-Figuren mit denselben Proportionen.',
    'g.set.folkShadow': 'Schatten der Menschen',
    'g.set.folkShadow.tip': 'Die Menschen in der Nähe werfen echte Schatten mit ihrer Gestalt (in die Schattenkarte gezeichnet, wie Möbel und Palmen) und stehen selbst im Schatten der Häuser. Braucht die Schatten (ab Ausgewogen); aus = ein weicher Fleck unter den Füßen.',
