    'g.set.bench': '⚡ Automatik',
    'g.set.bench.tip': 'Misst 3 Sekunden lang und stellt Stufe und Sichtweite so ein, dass es flüssig läuft.',
    'g.set.sweep': '📊 Stufentest',
    'g.set.sweep.tip': 'Misst jede Stufe nacheinander (je 3 Sekunden, gut 20 Sekunden insgesamt) an dieser Stelle der Welt und sagt, welche Stufe ruckelfrei läuft und welche noch spielbar ist. Deine Einstellungen bleiben wie sie sind.',
    'g.sweep.title': 'Stufentest',
