    'g.set.volVoice': 'Stimmen',   // e-music
    'g.set.volVoice.tip': 'Funkes Piepsen und das Plaudern der Dorfleute.',
    'g.set.calmMusic': 'Ruhige Musik',
    'g.set.calmMusic.tip': 'Längere Stille zwischen den Stücken, keine Trommeln, leiser im Kampf.',
    'g.set.musicLess': 'Musik seltener',   // e-score2
    'g.set.musicLess.tip': 'Mehr als doppelt so lange Pausen zwischen den Stücken – dazwischen hörst du die Natur.',
    'g.set.wx': 'Wetter',
    'g.set.wx.tip': 'Wie oft Regen, Nebel und Gewitter kommen.',
    'g.set.wx.normal': 'Normal',
    'g.set.wx.normal.tip': 'Der Himmel wechselt zwischen klar, bewölkt, Nebel, Regen, Gewitter und Schnee.',
    'g.set.wx.calm': 'Ruhig',
    'g.set.wx.calm.tip': 'Nur klar und bewölkt: kein Regen, kein Gewitter.',
    'g.set.wx.off': 'Aus',
    'g.set.wx.off.tip': 'Immer klarer Himmel.',
    'g.set.natSound': 'Natur-Klänge',
    'g.set.natSound.tip': 'Wind, Vögel, Grillen und Wasser.',
    'g.set.natSound.synth': 'Synthetisch',
    'g.set.natSound.synth.tip': 'Im Spiel erzeugt, ohne Aufnahmen.',
    'g.set.natSound.off': 'Aus',
    'g.set.natSound.off.tip': 'Keine Natur-Klänge.',
    'g.set.fov.tip': 'Wie weit das Bild seitlich reicht: größer sieht weiter, kleiner wirkt näher.',
    'g.set.sens.tip': 'Wie schnell sich der Blick mit der Maus dreht.',
    'g.set.rawInput': 'Rohe Mausdaten',
    'g.set.rawInput.tip': 'Die Maus bewegt sich genau so, wie du sie schiebst, ohne Beschleunigung des Systems.',
    'g.set.mouseSmooth': 'Mausglättung',
    'g.set.mouseSmooth.tip': 'Der Blick gleitet weicher, reagiert aber etwas später.',
    'g.set.invertY.tip': 'Maus nach oben schaut nach unten, wie in manchen Flugspielen.',
    'g.set.viewBob.tip': 'Das Bild wippt beim Gehen leicht mit.',
    'g.set.turnInertia.tip': 'Die Kamera folgt der Maus mit einem Hauch Verzögerung — wie ein Kopf, der sich dreht.',
    'g.set.mouseSteer.tip': 'Das Schiff fliegt, wohin du schaust. Aus: Die Maus schaut sich nur um, mit gedrückter rechter Taste lenkst du.',
    'g.set.camShake.tip': 'Tempo, Boost und Stöße rütteln die Kamera ein wenig.',
    'g.set.airLife.tip': 'Staub im Sonnenstrahl, Pollen, Glühwürmchen, fallende Blätter, Schnee und Vögel — je nach Stufe weniger; auf Sehr niedrig nur Glühwürmchen und Schnee.',
    'g.set.anim.tip': 'Radar-Bildschirme, das Portal-Energiefeld, blinkende Konsolen und pulsierende Lichtleisten bewegen sich. Auf Sehr niedrig aus.',
    'g.set.sprintMode': 'Sprinten',
    'g.set.sprintMode.tip': 'Halten: nur solange die Taste gedrückt ist. Umschalten: einmal an, wieder aus.',
    'g.set.sprintMode.hold': 'Halten',
    'g.set.sprintMode.hold.tip': 'Sprint läuft, solange Strg oder 2× W gedrückt bleibt.',
    'g.set.sprintMode.toggle': 'Umschalten',
    'g.set.sprintMode.toggle.tip': 'Einmal drücken: sprinten. Wieder drücken oder stehen bleiben: gehen.',
    'g.set.autoJump': 'Automatisch springen',
