    'g.set.vibrate': 'Vibration beim Landen',
    'g.set.vibrate.tip': 'Ein Controller vibriert, wenn du nach einem Sprung oder Sturz landest.',
    'g.set.keys.open': '⌨ Tasten & Steuerung ▸',
    'g.set.keys.open.tip': 'Jede Taste neu belegen. Doppelte Belegungen werden angezeigt.',
