    'g.talk.elderSays': ['{y} Jahre alt und ich gehe immer noch jeden Tag in den Park.', 'Zu meiner Zeit gab es keine Schwebebahn. Wir sind gelaufen!', 'Meine Enkel halten mich jung.'],
    'g.talk.r.teacher': ['Zweiundzwanzig Kinder, und jedes fragt nach den Ringen.', 'Heute Abend korrigiere ich Hausaufgaben — die Zeichnungen sind wunderbar.'],
    'g.talk.r.worker': ['Vier Maschinen, ein Förderband, diesen Monat kein Unfall.', 'Die Fabrik summt wie ein Raumschiff-Triebwerk.'],
    'g.talk.r.office': ['E-Mails, Besprechungen, noch mehr E-Mails. Aber die Aussicht aus dem dritten Stock!', 'Wir stellen ein, falls du tippen kannst.'],
    'g.talk.r.barista': ['Ich kenne die Bestellung von jedem Stammgast auswendig.', 'Die Terrasse ist bei Sonnenuntergang der beste Platz der Stadt.'],
    'g.talk.r.mayor': ['Der Brunnenplatz hat ein Vermögen gekostet, aber schau ihn dir an!', 'Das Rathaus ist jeden Morgen offen. Bring deine Ideen mit.'],
