    // ---- was die Leute im Dorf sagen (Sprechblasen)
    'g.folk.hello': ['Hallo!', 'Hallo, Reisender!', 'Oh! Hallo!', 'Schön, dich zu sehen!', 'Willkommen, willkommen!', 'Hey! Schöner Tag, oder?', 'Sei gegrüßt, Freund!'],
    'g.folk.helloBack': ['Willkommen zurück, {p}!', '{p}! Du bist wieder da!', 'Hallo nochmal, {p}!', 'Da ist ja unser Lieblingsbesuch!'],
    'g.folk.morning': ['Guten Morgen, {n}!', 'Morgen, {n}! Gut geschlafen?', 'Aufstehen, {n}!', 'Was für ein Sonnenaufgang!'],
    'g.folk.evening': ['Schöner Abend, {n}.', 'Schau dir den Himmel an …', 'Bald geht’s nach Hause.', 'Die Lampen sind heute Abend so hübsch.'],
    'g.folk.night': ['Psst … alle schlafen.', 'Die Sterne sind so hell.', 'Kannst du auch nicht schlafen?'],
    'g.folk.family': ['Hab dich lieb, {n}!', 'Hast du gegessen, {n}?', 'Komm mal her, du!', 'Ich bin stolz auf dich, {n}.', 'Gehen wir später zum Platz, {n}?'],
    'g.folk.kidParent': ['Mama! Papa! Schaut mal!', 'Darf ich noch ein bisschen spielen?', 'Ich hab einen glitzernden Stein gefunden!', 'Ich hab euch lieb!', 'Trägst du mich?'],
    'g.folk.parentKid': ['Vorsicht, {n}!', 'Vor dem Dunkelwerden zu Hause, {n}!', 'Hast du die Schafe gefüttert, {n}?', 'Das ist mein {n}!'],
    'g.folk.friends': ['Wie geht’s der Familie, {n}?', 'Hast du schon von {fact} gehört?', 'Schönes Wetter dafür.', 'Ha! Der war gut, {n}.', 'Später einen Tee, {n}?', 'Bis später auf dem Platz!'],
    'g.folk.farm': ['Der Weizen glänzt heute golden.', 'Wachst, kleine Pflänzchen!', 'Wieder eine gute Ernte!', 'Etwas Regen wäre schön.', 'Bitte nicht auf die Felder treten!'],
    'g.folk.bake': ['Frisches Brot, noch warm!', 'Mmm, riechst du das?', 'Heute Zimt oder Honig?', 'Wer will ein Brötchen?'],
    'g.folk.forge': ['*kling* *klang*', 'Heißes Eisen, Abstand!', 'Dieser Hammer ist älter als ich.', 'Fast fertig …'],
    'g.folk.read': ['Faszinierend …', 'Wusstest du, dass die Ringe unseres Planeten aus Eis sind?', 'Psst, ich lese.', 'So viele Geschichten, so wenig Zeit.'],
    'g.folk.build': ['Noch eine Wand!', 'Zweimal messen, einmal sägen.', 'Am Haus {s} geht es voran!', 'Reichst du mir das Brett?'],
    'g.folk.garden': ['Hallo, kleine Blumen.', 'Die Rosen gedeihen prächtig!', 'Ein Garten tut der Seele gut.'],
    'g.folk.patrol': ['Alles ruhig.', 'Ich halte heute Nacht Wache.', 'An mir kommt nichts vorbei.', 'Bleib in der Nähe der Lampen.'],
    'g.folk.play': ['Fangen! Du bist dran!', 'Du kriegst mich nicht!', 'Juhu!', 'Spielen wir Verstecken!', 'Ich bin Raumschiff-Pilot! Wrrrm!'],
    'g.folk.rain': ['Gut für die Felder!', 'Ich mag das Geräusch von Regen.', 'Regenschirm-Wetter!'],
    'g.folk.ship': ['Guck mal! Ein Schiff!', 'Wo die wohl hinfliegen?', 'Irgendwann fliege ich auch so eins!', 'Wow, wie schnell das ist!'],
    'g.folk.meteor': ['Eine Sternschnuppe! Wünsch dir was!', 'Hast du das gesehen?!'],
    'g.folk.danger': ['Monster! Alle rein!', 'Alle nach Hause!', 'Bleib weg!'],
    'g.folk.hurt': ['Au! Hey!', 'Warum machst du das?!', 'Autsch … das war nicht nett.'],
    'g.folk.thanks': ['Für mich? Danke!', 'Du bist zu lieb!', 'Oh, das ist toll!', 'Das wäre doch nicht nötig gewesen!'],
    'g.folk.sleep': ['Zzz …', 'Mmm … noch fünf Minuten …', 'Zzz … Sterne …'],
    'g.folk.eat': ['Lecker!', 'Gibst du mir das Brot?', 'Wer hat das gekocht? Fantastisch!'],
    'g.folk.build_done': ['Das neue Haus ist fertig! Willkommen, Familie {s}!', 'Geschafft! Ein neues Zuhause!'],
    'g.folk.repair': ['Oh, ein Loch im Haus {s}. Ich repariere das!', 'Wie neu!'],
    'g.folk.vandal': ['Hey! Das ist das Haus {s}!', 'Ohje … ich sag den Baumeistern Bescheid.'],
    'g.folk.lunch': 'Mittagessen, alle zusammen! ♪',
    'g.folk.newHome': ['Unser neues Zuhause! Danke euch allen!', 'Es ist perfekt!'],
    'g.folk.builtFirst': ['Was für ein schönes Haus! Dürfen wir hier wirklich wohnen?', 'Das hast du für uns gebaut? Danke!', 'Unser eigenes Zuhause!'],
    'g.folk.builtKids': ['Juhu, ein neues Zuhause!', 'Ich nehm das obere Bett!', 'Es ist perfekt!'],
    'g.folk.school': ['{a} plus {b} ist {c}!', 'Darf ich antworten? Bitte!', 'Die Ringe sind aus Eis, oder?', 'Mein Bild ist fertig!', 'Ist schon Pause?', 'A wie Äther!'],
    'g.folk.cafe': ['Der beste Kaffee in {v}.', 'Noch ein Croissant …', 'Mittagspause! Endlich.', 'Prost!', 'Dieser Latte ist perfekt.'],
    'g.folk.parkElder': ['Ah, der Brunnen. So friedlich.', 'Sechzig Jahre lang habe ich hier die Vögel gefüttert.', 'Setz dich, Kind, ruh dich etwas aus.', 'So ein schöner Abend.'],
    'g.folk.park': ['Was für ein Tag.', 'Der Brunnen ist so beruhigend.', 'Endlich frische Luft.'],
    'g.folk.library': ['Was heißt dieses Wort?', 'Das kann ich lesen!', 'Ooh, Bilder!'],
    'g.folk.basket': 'Ein Korb {crop} für die Bäckerei!',
    'g.folk.progress': 'Das neue Haus ist zu {pct}% fertig!',
    'g.folk.bread': 'Frisches Brot für die {s}!',
    'g.folk.pilot': ['Check vor dem Start …', 'Die Triebwerke sehen gut aus.', 'Eines Tages fliege ich sie bis zu den Ringen.'],
    'g.folk.teach': ['{n}, was ist {a} mal {b}?', 'Augen zur Tafel, alle!', 'Heute: die Planeten und ihre Ringe!', 'Sehr gut! Wer noch?', 'Schlagt eure Bücher auf Seite {p} auf.'],
    'g.folk.teachIdle': ['Der Unterricht fängt gleich an.', 'Ich wische mal die Tafel.', 'Hausaufgabe: malt die Schwebebahn!'],
    'g.folk.factory': ['Zweite Schicht, alle Maschinen auf Grün.', 'Noch eine Ladung Rumpfplatten fertig.', 'Vorsicht am Förderband!', 'Kaffeepause in zehn Minuten.', 'Qualitätsprüfung bestanden.'],
    'g.folk.office': ['Nur schnell die Post beantworten.', 'Die Quartalszahlen sehen gut aus.', 'Besprechung um drei.', 'Tabellen … so viele Tabellen.', 'Hast du unsere neuen Büropflanzen gesehen?'],
    'g.folk.barista': ['Zwei Latte kommen sofort!', 'Frische Croissants, noch warm.', 'Hafermilch? Natürlich.', 'Setz dich auf die Terrasse!'],
    'g.folk.control': ['Flugleitung: zwei Schiffe im Anflug.', 'Telemetrie normal.', 'Kurs berechnet. Start frei!', 'Ich behalte den Himmel im Blick …'],
    'g.folk.cashier': ['Der Nächste, bitte!', 'Alles gefunden?', 'Einen schönen Tag noch!'],
    'g.folk.clerk': ['Ich fülle die Regale auf.', 'Heute frische Lieferung!', 'In Gang drei gibt’s ein Angebot.'],
    'g.folk.heal': 'Du siehst verletzt aus — komm, ich helfe dir.',
