    'g.set.hudMode': 'Anzeigen am Rand (HUD)',
    'g.set.hudMode.tip': 'Automatisch: Leiste, Herzen, Karte und Kompass erscheinen, wenn sie etwas zu sagen haben, und blenden sanft aus — Gefahr wird nie versteckt. Immer: alles bleibt stehen. Minimal: fast nichts.',
    'g.set.hudMode.auto': 'Automatisch',
