    "g.pt.skip": "Leertaste: überspringen",
    "g.pt.menu": "🌍 Reisen",
    "g.pt.menuTip": "Der Leuchtpfad: zu einem Lieblingsort, ohne zu steuern (oder K halten)",
    "g.pt.holdK": "K halten: Reisen",
    "g.pt.guest": "Der Gastgeber reist — du wirst gefragt, ob du mitreist",
    "g.pt.busy": "Gerade unterwegs",
    "g.pt.gate": "Das Tor leuchtet auf …",
    "g.pt.kind.home": "Herzwelt",
    "g.pt.kind.deep": "Tiefe Welt",
    "g.pt.kind.isles": "Himmelsinseln",
    "g.pt.kind.moon": "Mond",
    "g.pt.kind.world": "Welt",
    "g.pt.kind.station": "Station",
    "g.pt.kind.exo": "Fremder Stern",
    "g.pt.kind.unknown": "Ort",
    "g.pt.kind.fav": "Lieblingsort",
    "g.pt.episode": "Erste Ankunft",
    "g.pt.fly": "Flug ×{v}",
    "g.set.flyFast": "Kreativ-Fluggeschwindigkeit",
    "g.set.flyFast.tip": "Nur Kreativ, allein: ×1 bis ×8 (oder Mausrad beim schnellen Fliegen). Im Mehrspieler immer ×1",
    "g.pt.flyMp": "Im Mehrspieler fliegt jeder ×1",
    "g.pt.slow": "Die Welt lädt — kurz langsamer",
    "g.pt.hook.home.1": "Hier hat alles angefangen — und Funke hat zum ersten Mal geblinkt.",
    "g.pt.hook.home.2": "Die Glocken der Stadt läuten, als hätten sie dich vermisst.",
    "g.pt.hook.home.3": "Irgendwo hier wartet dein Bett. Und vielleicht ein warmer Kakao.",
    "g.pt.hook.home.4": "Über dem Tortempel kreisen die Schwalben. Sie kennen dich schon.",
    "g.pt.hook.deep.1": "Hier unten glüht der Stein, als hätte er ein Herz.",
    "g.pt.hook.deep.2": "Kapitän Jonte sagt, hier unten verliert man die Zeit. Und findet Edelsteine.",
    "g.pt.hook.deep.3": "Psst — die Höhle summt ein Lied, das niemand geschrieben hat.",
    "g.pt.hook.isles.1": "Hier schwimmen Inseln im Wind, und die Wolkenrochen sagen hallo.",
    "g.pt.hook.isles.2": "Lumi hat hier ihren ersten Drachen steigen lassen. Er fliegt noch immer.",
    "g.pt.hook.isles.3": "Spring nicht zu weit — oder doch, die nächste Insel fängt dich auf.",
    "g.pt.hook.moon.1": "Hier hat Lumis Opa den Eiswächter gefunden …",
    "g.pt.hook.moon.2": "Hier steht Amarant so groß am Himmel, dass du ihn fast anfassen willst.",
    "g.pt.hook.moon.3": "Der Staub hier ist älter als jede Stadt auf Herzwelt.",
    "g.pt.hook.moon.4": "Oskar schwört, nachts singen hier die Krater.",
    "g.pt.hook.world.1": "Ein ganzer Himmel in einer neuen Farbe — nur für dich.",
    "g.pt.hook.world.2": "Selma hat hier einmal ein Leuchtfeuer flackern sehen. Ganz kurz.",
    "g.pt.hook.world.3": "Fremder Boden, weiter Blick. Willkommen!",
    "g.pt.hook.station.1": "Im Hydrogarten wachsen Tomaten im Kreis um den Planeten.",
    "g.pt.hook.station.2": "Hier oben blinkt das rote Leuchtfeuer — das erste, das Funke wiedergefunden hat.",
    "g.pt.hook.station.3": "Durch das Fenster dreht sich die ganze Welt. Ganz langsam.",
    "g.pt.hook.exo.1": "Eine fremde Sonne. Und trotzdem fühlt sich der Wind freundlich an.",
    "g.pt.hook.exo.2": "So weit war noch nie jemand von Herzwelt. Außer dir.",
    "g.pt.hook.exo.3": "Funke misst: Licht, Luft, Abenteuer. Alles da.",
    "g.pt.hook.fav.1": "Dein Lieblingsort. Er hat auf dich gewartet.",
    "g.pt.hook.fav.2": "Genau hier war es so schön. Und ist es noch.",
    "g.pt.hook.fav.3": "Zurück an deinem Platz. Funke dreht eine Freudenrunde.",
    "g.pt.hook.unknown.1": "Ein neuer Ort, ein neues Kapitel.",
    "g.pt.hook.unknown.2": "Wer weiß, was hier auf dich wartet?",
    "g.pt.ep.moon1.1": "Bip! Spürst du das? Unter dem Eis summt etwas.",
    "g.pt.ep.moon1.2": "Das ist der Takt aus Opas Notizbuch! Wir sind auf der richtigen Spur.",
    "g.pt.ep.moon2.1": "Ich hab dir ein Mondbrot eingepackt. Falls du Hunger kriegst.",
    "g.pt.ep.moon2.2": "Oskar, es gibt hier keine Bäckerei!",
    "g.pt.ep.moon2.3": "Eben. Deshalb ja.",
    "g.pt.ep.world1.1": "Schau dir diese Farben an. Kein Maler hätte sich das getraut.",
    "g.pt.ep.world1.2": "Ich speichere das als Lieblingshimmel Nummer sieben. Nein — Nummer eins.",
    "g.pt.ep.world2.1": "Kapitän, wir sind gelandet, ohne ein Steuer anzufassen!",
    "g.pt.ep.world2.2": "Hmpf. Früher sind wir noch gerudert. Durch den Weltraum. Bergauf.",
    "g.pt.ep.deep1.1": "Siehst du die Adern im Stein? Die leuchten wie Laternen in einer Gasse.",
    "g.pt.ep.deep1.2": "Funke leuchtet zurück! Hallo, Stein. Wir sind Freunde.",
    "g.pt.ep.deep2.1": "Es ist so still hier … fast wie die Stille aus der Geschichte.",
    "g.pt.ep.deep2.2": "Nein, Kleiner. Diese Stille ist nur ein Höhlenschlaf. Hör: Tropfen.",
    "g.pt.ep.isles1.1": "Hüpf! Die Inseln wackeln, wenn man lacht.",
    "g.pt.ep.isles1.2": "Messung: Wackeln plus zwölf Prozent. Wir lachen zu viel. Weiter so!",
    "g.pt.ep.stn1.1": "Der Leuchtpfad hat dich bis hier hoch gebracht? Dann ist das Netz wieder wach.",
    "g.pt.ep.stn1.2": "Ein Faden nach dem anderen, Meisterin. Bald leuchtet alles.",
    "g.pt.ep.stn2.1": "Achtung, Schwerkraft dreht sich im Kreis! Nicht schwindelig werden.",
    "g.pt.ep.stn2.2": "Zu spät. Aber es ist ein schöner Schwindel.",
    "g.pt.ep.exo1.1": "Ein anderer Stern … und trotzdem ein Leuchtfeuer am Horizont. Siehst du es?",
    "g.pt.ep.exo1.2": "Dann war das Netz einmal größer, als wir dachten. Viel größer.",
    "g.pt.ep.exo2.1": "Notiz an mich: Ich bin der erste Funke unter dieser Sonne.",
    "g.pt.ep.exo2.2": "Zweite Notiz: Zusammen mit dir. Das ist noch besser.",
    "g.pt.ep.home1.1": "Durch das große Tor nach Hause. Das hat das Netz seit der Stille nicht mehr geschafft!",
    "g.pt.ep.home1.2": "Dann ist das Tor wieder unser Tor. Für alle Wege, die noch kommen.",
    "g.pt.ep.any1.1": "Kapitän, wie hat dir die Reise gefallen?",
    "g.pt.ep.any1.2": "Zu kurz. Ich wollte noch winken.",
    "g.pt.ep.any2.1": "Jedes Tor, durch das du gehst, merkt sich dich. So wurden die Wege gebaut.",
    "g.pt.ep.any2.2": "Dann bauen wir gerade einen Weg? Nur indem wir reisen? Bip!",
    "g.pt.ep.any3.1": "Ich habe eine Postkarte für Selma gemacht. Sie ist ein bisschen verwackelt.",
    "g.pt.ep.any3.2": "Verwackelt ist perfekt. Dann sieht man, dass es eine echte Reise war.",
    // ---- e-portal end
