    "g.fairy.ask.lanterns": "Oh … hallo. Der Wind hat unsere drei Laternen fortgeweht. Ohne sie findet keiner heim. Hilfst du uns? (Noch einmal [V])",
    "g.fairy.go.lanterns": "Danke! Sie leuchten irgendwo um den Baum herum. Oder bau uns drei Lichter an die Tür!",
