    "g.fairy.lan.built": "🏮 Deine Lichter leuchten an der Tür – sag Tüpfel Bescheid!",
    "g.fairy.ask.lost": "*schnief* Ich hab mich verflogen … Ich wohne bei den Tanzsteinen. Bringst du mich heim? (Noch einmal [V])",
    "g.fairy.go.lost": "Ich flieg dir nach! Nicht zu schnell, ja?",
    "g.fairy.still.lost": "Bist du noch da? Ich folge dir!",
    "g.fairy.lost.wait": "Warte auf mich!",
    "g.fairy.lost.home": "Da sind ja alle! Danke, danke, danke!",
    "g.fairy.thanks.lost": "Heute Nacht tanze ich für dich mit!",
    "g.fairy.ask.bridge": "*gähn* … Die Wolkenbrücke schläft, bis die Sonne aufgeht. Spiel ihr Lied auf den Singsteinen, dann wacht sie auf. (Noch einmal [V])",
    "g.fairy.go.bridge": "Hör gut zu … ich summ es dir vor.",
    "g.fairy.still.bridge": "Noch mal? Hör gut zu …",
    "g.fairy.dusel.hum": "Hmm-hmm-hmmm-hm …",
    "g.fairy.dusel.yawn": "*gääähn* … Oh, Besuch? Sprich noch mal mit mir, ich bin gleich wach.",
    "g.fairy.bridge.awake": "Sie ist wach! Geh auf die Wolken – sie tragen dich.",
    "g.fairy.thanks.bridge": "Die Brücke summt jetzt dein Lied. Schön, oder?",
    "g.fairy.garden.up": "🌸 Der Schwebegarten. Hier oben ist es still und warm.",
    "g.fairy.ask.riddle": "Willkommen im Kreis. Wer meine drei Rätsel löst, dem schenkt der Mond ein Licht. Magst du? (Noch einmal [V])",
    "g.fairy.go.riddle": "Hör zu. Die Antwort steht auf einem der drei Steine vor mir.",
    "g.fairy.still.riddle": "Denk in Ruhe nach.",
    "g.fairy.rid.right": "Richtig!",
    "g.fairy.rid.wrong": "Nicht ganz. Hör noch einmal hin.",
    "g.fairy.thanks.riddle": "Klug und geduldig – so mag es der Mond.",
    "g.fairy.ask.hat": "Hihi! Schau mal, mein neuer Hut! … Na gut, er ist von Tüpfel. Fang mich, dann geb ich ihn zurück! (Noch einmal [V])",
    "g.fairy.go.hat": "Fang mich doch!",
    "g.fairy.still.hat": "Zu langsam! Hihi!",
    "g.fairy.hat.hop1": "Fast! Hüpf-hüpf!",
    "g.fairy.hat.hop2": "Hihi, noch einmal!",
    "g.fairy.hat.done": "Du hast mich! Hier, der Hut – sag Tüpfel, es war nur Spaß.",
    "g.fairy.thanks.hat": "Das war lustig! Wieder fangen spielen?",
    "g.fairy.borke.0": "Wer klopft da so leise? Ach, ein Wanderer. Unser Tüpfel braucht Hilfe – sprich mit ihm.",
    "g.fairy.borke.during": "Die Kleinen warten auf ihre Laternen. Du schaffst das.",
    "g.fairy.borke.after": "Komm herein, wann immer du magst. Im Schlummerbaum ist es warm.",
    "g.fairy.chat.borke.0": "Der Baum schläft seit hundert Wintern. Wir wohnen leise.",
    "g.fairy.chat.borke.1": "Hörst du ihn atmen? Ganz langsam.",
    "g.fairy.chat.borke.2": "Setz dich, ruh dich aus.",
    "g.fairy.chat.saemli.0": "Ich bin den ganzen weiten Weg mitgekommen. Hier wachsen wir jetzt!",
    "g.fairy.chat.saemli.1": "Wiegelind hat uns hier ausgesät. Siehst du, wie es leuchtet?",
    "g.fairy.chat.saemli.2": "Dreimal blinken heißt: Ich bin da. Probier's mal!",
    "g.fairy.chat.fern0.0": "Wir kommen von ganz weit her, von Wiegelinds Reise.",
    "g.fairy.chat.fern0.1": "Unser Häuschen ist noch ganz neu. Gefällt es dir?",
    "g.fairy.chat.fern0.2": "Nachts summen wir ihr Lied, damit die Pilze wachsen.",
    "g.fairy.chat.fern1.0": "Psst, die Samen schlafen noch.",
    "g.fairy.chat.fern1.1": "Hier ist es warm und weich. Ein gutes Zuhause.",
    "g.fairy.chat.fern1.2": "Wenn du gut zuhörst, hörst du die Wiese flüstern.",
    "g.fairy.chat.folk0.0": "Hallo! Schöne Füße hast du. So groß!",
    "g.fairy.chat.folk0.1": "Ich sammle Tautropfen. Willst du einen?",
    "g.fairy.chat.folk0.2": "Pssst, der Baum schläft.",
    "g.fairy.chat.folk1.0": "Heute backen wir Moosküchlein!",
    "g.fairy.chat.folk1.1": "Hast du schon die Quelle gesehen? Sie glitzert.",
    "g.fairy.chat.folk1.2": "Nachts tanzen die Lichter im Steinkreis.",
    "g.fairy.rid.0.q": "Ich trage ein Licht im Bauch und blinke im Gras, doch wärme niemanden. Wer bin ich?",
    "g.fairy.rid.0.a0": "Ein Glühwürmchen",
    "g.fairy.rid.0.a1": "Eine Kerze",
    "g.fairy.rid.0.a2": "Der Mond",
    "g.fairy.rid.1.q": "Ich falle vom Himmel ohne Flügel, glitzere wie ein Stern und schmelze in deiner Hand.",
    "g.fairy.rid.1.a0": "Eine Schneeflocke",
    "g.fairy.rid.1.a1": "Ein Blatt",
    "g.fairy.rid.1.a2": "Ein Vogel",
    "g.fairy.rid.2.q": "Ich zeige dir dein Gesicht und bin doch kein Spiegel. Wirfst du einen Stein, zerbreche ich – und bin gleich wieder heil.",
    "g.fairy.rid.2.a0": "Ein stiller See",
    "g.fairy.rid.2.a1": "Ein Fenster",
    "g.fairy.rid.2.a2": "Ein Teller",
    "g.fairy.rid.3.q": "Ich gehe mit dir, wohin du gehst, doch nur, wenn ein Licht scheint. Wer bin ich?",
    "g.fairy.rid.3.a0": "Dein Schatten",
    "g.fairy.rid.3.a1": "Dein Hut",
    "g.fairy.rid.3.a2": "Der Wind",
    "g.fairy.rid.4.q": "Ich habe sieben Farben und keinen Pinsel. Ich komme nach dem Regen, wenn die Sonne lacht.",
    "g.fairy.rid.4.a0": "Ein Regenbogen",
    "g.fairy.rid.4.a1": "Eine Blumenwiese",
    "g.fairy.rid.4.a2": "Ein Malkasten",
    "g.fairy.rid.5.q": "Am Morgen liege ich wie Perlen auf dem Gras, mittags bin ich fort, und keiner hat mich weggenommen.",
    "g.fairy.rid.5.a0": "Der Tau",
    "g.fairy.rid.5.a1": "Die Steine",
    "g.fairy.rid.5.a2": "Die Käfer",
    "g.fairy.rid.6.q": "Ich bin ein Haus ohne Tür, und drinnen wartet ein Vogel, der noch nie geflogen ist.",
    "g.fairy.rid.6.a0": "Ein Ei",
    "g.fairy.rid.6.a1": "Ein Nest",
    "g.fairy.rid.6.a2": "Eine Wolke",
    "g.fairy.rid.7.q": "Ich wachse aus einem Korn, trage eine Krone aus Gold und drehe mein Gesicht der Sonne nach.",
    "g.fairy.rid.7.a0": "Eine Sonnenblume",
    "g.fairy.rid.7.a1": "Ein König",
    "g.fairy.rid.7.a2": "Ein Pilz",
