    "g.ss.f.lichter": "Lichterbaumnacht",
    "g.ss.f.lichter.what": "die Winternacht der Lichter: ein riesiger Laternenbaum, Kerzen in allen Fenstern",
    "g.ss.f.gezeiten": "Gezeitenleuchten",
    "g.ss.f.gezeiten.what": "das Fest der Wellari: Lichter steigen wie Gischt in den Abend",
