    "g.set.seasons": "Jahreszeiten",
    "g.set.seasons.tip": "Frühling, Sommer, Herbst und Winter auf der Herzwelt — Blüten, Gold, buntes Laub, Schnee und gefrorene Teiche, Feste im Dorf. Sehr niedrig: nur die Farben.",
    "g.set.seasonPick": "Jahreszeit",
    "g.set.seasonPick.tip": "Kreativ-Welten: eine Jahreszeit festhalten. Sonst dreht sich das Jahr von selbst.",
    "g.set.seasonPick.auto": "Automatisch",
    "g.set.seasonPick.auto.tip": "Alle drei Tage kommt die nächste Jahreszeit.",
    "g.set.seasonPick.kreativ": "In Kreativ-Welten bleibt es bei dieser Jahreszeit.",
    "g.wd.p.festivals": "Feste",
    "g.ss.prep": "{v} schmückt den Platz — morgen Abend ist {f}. Du bist eingeladen!",
    "g.ss.today": "Heute Abend: {f} in {v}.",
    "g.ss.begun": "{ico} {f} in {v} hat begonnen — komm zum Platz!",
    "g.ss.book": "📖 Neu im Wanderbuch: {f}",
    "g.ss.invite": ["Morgen ist {f} — kommst du auch?", "Wir schmücken für {f}! Morgen Abend, auf dem Platz.", "Hilfst du morgen mit? {f} ist das schönste Fest!", "Komm morgen zum {f}, ja?"],
    "g.ss.deco": ["Noch ein Stück höher!", "So, und hier noch eins.", "Sieht schon festlich aus!", "Hältst du mal kurz?"],
    "g.ss.mayor.bluete": "Willkommen zum Blütenreigen! Der Frühling tanzt mit uns.",
    "g.ss.mayor.drachen": "Willkommen zum Drachenwindtag! Lasst sie steigen!",
    "g.ss.mayor.tafel": "Willkommen zum Laubtafelfest! Setzt euch, es ist genug für alle da.",
    "g.ss.mayor.lichter": "Willkommen zur Lichterbaumnacht! Jedes Licht ist ein guter Wunsch.",
    "g.ss.mayor.native": "Willkommen, Freund! Heute ist {f} — feiere mit uns!",
    "g.ss.chat.bluete": ["Riech mal, die Blüten!", "Ich hab einen Kranz gebunden!", "Die Blütenblätter fliegen überall hin!", "Frühling, endlich!"],
    "g.ss.chat.drachen": ["Meiner fliegt am höchsten!", "Halt die Schnur fest!", "Guck, der rote da oben!", "Mehr Wind, bitte!"],
    "g.ss.chat.tafel": ["Noch ein Stück Kuchen?", "Die Suppe ist köstlich!", "Reich mir bitte das Brot.", "So eine lange Tafel!"],
    "g.ss.chat.lichter": ["So viele Lichter!", "Ich hab mir was gewünscht.", "Wie warm die Kerzen leuchten.", "Der Baum ist größer als letztes Jahr!"],
    "g.ss.chat.native": ["Schön, dass du da bist!", "Das ist unser schönstes Fest.", "Sieh nur, die Lichter!", "Feiern ist besser zusammen."],
    "g.ss.act.blossom": "Einen Blütenkranz an den Bogen hängen",
    "g.ss.act.blossomDone": "Dein Kranz hängt am Bogen! ({n} Kränze)",
    "g.ss.act.kite": "Den Drachen fangen",
    "g.ss.act.kiteDone": "Gefangen! Ein Kind bekommt seinen Drachen zurück. ({n})",
    "g.ss.act.food": "An der langen Tafel mitessen",
    "g.ss.act.foodDone": "Du teilst {food} mit dem Dorf. Mmh!",
    "g.ss.food": ["Apfelkuchen", "Kürbissuppe", "Nussbrot", "Pflaumenkuchen", "Honigbrot"],
    "g.ss.act.lantern": "Eine Laterne an den Lichterbaum hängen",
    "g.ss.act.lanternDone": "Deine Laterne leuchtet am Baum! ({n} Laternen)",
    "g.ss.act.native": "Mitfeiern",
    "g.ss.act.nativeDone": "Die {sp} freuen sich: du feierst {f} mit!",
    "g.ss.thanks": ["Danke dir!", "Wie schön!", "Du gehörst dazu!", "Juhu!"],
